package convert

// convert_test.go — the fidelity pins of issue #7 against the committed
// real-Excel-2003 fixture (testdata/ledger-2003-format.xls, generated by
// LibreOffice from a ledger-shaped source — double-row merged header,
// RK-compressed prices, FORMULA-computed amounts, date columns, Chinese
// text). The fixture is binary and committed, so these tests run offline
// and deterministically.

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/xuri/excelize/v2"
)

const fixtureRel = "../../testdata/ledger-2003-format.xls"

func fixturePath(t *testing.T) string {
	t.Helper()
	p, err := filepath.Abs(fixtureRel)
	if err != nil {
		t.Fatalf("abs fixture: %v", err)
	}
	if _, err := os.Stat(p); err != nil {
		t.Skipf("fixture not present: %v", err)
	}
	return p
}

// raw reads a cell with RawCellValue so numbers/dates assert as stored
// (numbers exact, dates as serials) instead of display formats.
func raw(t *testing.T, f *excelize.File, sheet, cell string) string {
	t.Helper()
	v, err := f.GetCellValue(sheet, cell, excelize.Options{RawCellValue: true})
	if err != nil {
		t.Fatalf("GetCellValue %s!%s: %v", sheet, cell, err)
	}
	return v
}

// TestConvertFidelityXLSX is the acceptance pin: sheet names survive,
// merges reproduce, numbers stay numbers (including the RK-compressed
// prices that upstream decoded 100x), dates stay dates, formula cells
// carry their cached results, text stays text.
func TestConvertFidelityXLSX(t *testing.T) {
	out := filepath.Join(t.TempDir(), "ledger-2003-format.xlsx")
	outs, err := ConvertFile(fixturePath(t), filepath.Dir(out), FormatXLSX)
	if err != nil {
		t.Fatalf("ConvertFile: %v", err)
	}
	if len(outs) != 1 || outs[0] != out {
		t.Fatalf("outputs = %v, want exactly [%s] (original file name preserved)", outs, out)
	}
	f, err := excelize.OpenFile(out)
	if err != nil {
		t.Fatalf("open converted: %v", err)
	}
	defer func() { _ = f.Close() }()

	// Sheet names, in order.
	names := f.GetSheetList()
	want := []string{"直供电", "转供电"}
	if len(names) != 2 || names[0] != want[0] || names[1] != want[1] {
		t.Fatalf("sheets = %v, want %v", names, want)
	}

	// Merged ranges of the double-row header (8 real merges; the fixture
	// writer also emits no 1×1 entries).
	merges, err := f.GetMergeCells("直供电")
	if err != nil {
		t.Fatalf("GetMergeCells: %v", err)
	}
	got := map[string]bool{}
	for _, m := range merges {
		got[m.GetStartAxis()+":"+m.GetEndAxis()] = true
	}
	for _, wantRange := range []string{
		"A1:A2", "B1:B2", "C1:D1", "E1:E2", "F1:F2", "G1:G2", "H1:H2", "I1:I2",
	} {
		if !got[wantRange] {
			t.Errorf("merged range %s missing (got %v)", wantRange, got)
		}
	}

	// Typed cell values (row 3 = first data row).
	for cell, wantRaw := range map[string]string{
		"A1": "站址编码", "C1": "电表示数", "C2": "起始读数", "D2": "截止读数",
		"A3": "HLJ-0001", "C3": "1280", "D3": "1410", "G3": "130",
		"H3": "0.85",  // RK-compressed with the x100 flag — the 100x bug pin
		"I3": "110.5", // FORMULA cached result (=G3*H3), upstream dropped formula cells
		"I4": "58.88",
	} {
		if gotv := raw(t, f, "直供电", cell); gotv != wantRaw {
			t.Errorf("直供电!%s = %q, want %q", cell, gotv, wantRaw)
		}
	}

	// Date cells: raw serials convert back to the source dates.
	for cell, wantDay := range map[string]string{
		"E3": "2026-01-01", "F3": "2026-01-31",
	} {
		serialStr := raw(t, f, "直供电", cell)
		s, err := strconv.ParseFloat(serialStr, 64)
		if err != nil {
			t.Fatalf("cell %s raw = %q: not a serial number: %v", cell, serialStr, err)
		}
		gotTime, err := excelize.ExcelDateToTime(s, false)
		if err != nil {
			t.Fatalf("ExcelDateToTime(%v): %v", s, err)
		}
		if gotTime.Format("2006-01-02") != wantDay {
			t.Errorf("直供电!%s = %v, want date %s", cell, gotTime, wantDay)
		}
	}

	// Text cells survive verbatim (Chinese, no mojibake).
	if gotv := raw(t, f, "转供电", "D2"); gotv != "补报两个月" {
		t.Errorf("转供电!D2 = %q, want 补报两个月", gotv)
	}
	if gotv := raw(t, f, "转供电", "C2"); gotv != "2026-01" {
		t.Errorf("转供电!C2 = %q, want 2026-01", gotv)
	}
}

// TestConvertToCSVSheets pins the csv container: one CSV per sheet under
// the original-name directory, dates ISO, numbers exact, headers intact.
func TestConvertToCSVSheets(t *testing.T) {
	outDir := t.TempDir()
	outs, err := ConvertFile(fixturePath(t), outDir, FormatCSV)
	if err != nil {
		t.Fatalf("ConvertFile csv: %v", err)
	}
	if len(outs) != 2 {
		t.Fatalf("csv outputs = %v, want one per sheet (2)", outs)
	}
	base := filepath.Join(outDir, "ledger-2003-format")
	直供电 := filepath.Join(base, "直供电.csv")
	转供电 := filepath.Join(base, "转供电.csv")
	body, err := os.ReadFile(直供电)
	if err != nil {
		t.Fatalf("read 直供电.csv: %v", err)
	}
	for _, wantLine := range []string{
		"站址编码,用户号,电表示数,,购电起始日,购电截止日,实际电量,单价,应付电费,",
		"HLJ-0001,U-1001,1280,1410,2026-01-01,2026-01-31,130,0.85,110.5,",
	} {
		if !strings.Contains(string(body), wantLine) {
			t.Errorf("直供电.csv missing line %q:\n%s", wantLine, body)
		}
	}
	body2, err := os.ReadFile(转供电)
	if err != nil {
		t.Fatalf("read 转供电.csv: %v", err)
	}
	if !strings.Contains(string(body2), "HLJ-2001,5000.5,2026-01,补报两个月,") {
		t.Errorf("转供电.csv missing data row:\n%s", body2)
	}
}

// TestConvertRejectsCorruptXLS: garbage bytes with a .xls name must
// produce an explicit per-file failure — never a silent skip, never a
// half-written output.
func TestConvertRejectsCorruptXLS(t *testing.T) {
	dir := t.TempDir()
	bad := filepath.Join(dir, "bad.xls")
	if err := os.WriteFile(bad, []byte("this is not an OLE compound file"), 0o644); err != nil {
		t.Fatalf("write bad.xls: %v", err)
	}
	outDir := filepath.Join(dir, "out")
	res, err := Run(dir, outDir, FormatXLSX, false)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	if res.Converted != 0 || res.Failed != 1 {
		t.Fatalf("result = converted %d failed %d, want 0/1", res.Converted, res.Failed)
	}
	if res.Files[0].Error == "" {
		t.Fatal("the corrupt file must carry an explicit error reason")
	}
	if _, err := os.Stat(filepath.Join(outDir, "bad.xlsx")); !os.IsNotExist(err) {
		t.Fatal("a corrupt input must not leave a half-written output")
	}
}

// TestConvertIdempotentContent pins acceptance #6: converting the same
// file twice yields identical content (per-cell values and merges).
func TestConvertIdempotentContent(t *testing.T) {
	dir := t.TempDir()
	_, err := ConvertFile(fixturePath(t), dir, FormatXLSX)
	if err != nil {
		t.Fatalf("first convert: %v", err)
	}
	first := filepath.Join(dir, "ledger-2003-format.xlsx")
	_, err = ConvertFile(fixturePath(t), dir, FormatXLSX)
	if err != nil {
		t.Fatalf("second convert: %v", err)
	}
	second := first // SaveAs overwrites the same deterministic path
	if first != second {
		t.Fatal("internal: idempotence test confused itself")
	}
	f, err := excelize.OpenFile(first)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer func() { _ = f.Close() }()
	if got := raw(t, f, "直供电", "I3"); got != "110.5" {
		t.Errorf("after re-conversion I3 = %q, want 110.5 (content stability)", got)
	}
	merges, _ := f.GetMergeCells("直供电")
	if len(merges) != 8 {
		t.Errorf("after re-conversion merges = %d, want 8", len(merges))
	}
}

// TestRunSkipsNonXLSInputs: a directory entry that is not .xls is not a
// target (skipped, no error, no output); a missing input is an error.
func TestRunSkipsNonXLSInputs(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "notes.txt"), []byte("hi"), 0o644); err != nil {
		t.Fatal(err)
	}
	res, err := Run(dir, t.TempDir(), FormatXLSX, false)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	if res.Converted != 0 || res.Failed != 0 {
		t.Fatalf("result = %+v, want nothing converted or failed", res)
	}
	if _, err := Run(filepath.Join(dir, "nope"), t.TempDir(), FormatXLSX, false); err == nil {
		t.Fatal("missing input must be an error")
	}
}
